import sys
plate = sys.stdin.read().strip()
letters, digits = plate[:3], plate[3:]
flags = set()
if all(c <= 'M' for c in letters):
    flags.add('B')
if all(c >= 'N' for c in letters):
    flags.add('E')
def direction(s):
    steps = [ord(b)-ord(a) for a,b in zip(s, s[1:])]
    if all(d == 1 for d in steps):
        return 'I'
    if all(d == -1 for d in steps):
        return 'D'
    return None
ld, dd = direction(letters), direction(digits)
if (ld is None) != (dd is None):
    flags.add(ld or dd)
if all('A' <= c <= 'F' for c in letters):
    flags.add('H')
if digits[0] != '0' and all('0' <= c <= '7' for c in digits):
    flags.add('O')
if letters == letters[::-1] or digits == digits[::-1]:
    flags.add('P')
if len(set(letters)) < 3 or len(set(digits)) < 4:
    flags.add('R')
numbers = list(map(int, digits))
if any(2*d == sum(numbers) for d in numbers):
    flags.add('S')
print(''.join(sorted(flags)) or 'NONE')
